public static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastSlash = -1;
    int lastBackslash = -1;
    for (int i = 0; i < filename.length(); i++) {
        char c = filename.charAt(i);
        if (c == '/') {
            lastSlash = i;
        } else if (c == '\\') {
            lastBackslash = i;
        }
    }
    return Math.max(lastSlash, lastBackslash);
}
